solution:
use xiom.io;

use xiom.math;
fn check_answer(a: Int, b: Int, guess: Int) -> Result[Str, Str] {
  let correct = a + b;
  if guess == correct {
    return Ok("Correct!");
  } else {
    return Err("Wrong, the answer was " + correct);
  }
}

fn main() -> Int {
  let a = math.random_int(1, 10);
  let b = math.random_int(1, 10);
  let guess = a + b;
  match check_answer(a, b, guess) {
    Ok(_) => { return 1; }
    Err(_) => { return 0; }
  }
}
